source_raw_tex:
\eqalignno{\int_Ef_1*f_2d\mu 
&=\iint\chi E(x+y)f_1(x)f_2(y)\mu(dx)\mu(dy)\cr 

oalign{
oindent (255G)} 
&=\iint\chi E(x+y)f_2(y)
u_1(dx)\mu(dy)\cr 

oalign{
oindent (because $x\mapsto\chi E(x+y)$ is Borel measurable)} 
&=\iint\chi E(x+y)
u_1(dx)
u_2(dy)\cr 

oalign{
oindent (because $(x,y)\mapsto\chi E(x+y)$ is 
Borel measurable, so $y\mapsto\int\chi E(x+y)
u_1(dx)$ 
is $
u_2$-integrable)} 
&=(
u_1*
u_2)(E).\cr}

target_raw_tex:
\eqalignno{\int_Ef_1*f_2d\mu
&=\iint\chi E(x+y)f_1(x)f_2(y)\mu(dx)\mu(dy)\cr

oalign{
oindent (255G)}
&=\iint\chi E(x+y)f_2(y)
u_1(dx)\mu(dy)\cr

oalign{
oindent (karena $x\mapsto\chi E(x+y)$ terukur Borel)}
&=\iint\chi E(x+y)
u_1(dx)
u_2(dy)\cr

oalign{
oindent (karena $(x,y)\mapsto\chi E(x+y)$
terukur Borel, sehingga $y\mapsto\int\chi E(x+y)
u_1(dx)$
terintegralkan terhadap $
u_2$)}
&=(
u_1*
u_2)(E).\cr}
